CREATE TABLE "Achats" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "Fournisseur" text NOT NULL,
    "TotalAmount" numeric NOT NULL,
    "PaidAmount" numeric NOT NULL,
    "DateAchat" timestamp with time zone NOT NULL,
    "Note" text,
    "CreatedAt" timestamp with time zone NOT NULL,
    "CreatedBy" integer,
    "UpdatedAt" timestamp with time zone,
    "UpdatedBy" integer,
    CONSTRAINT "PK_Achats" PRIMARY KEY ("Id")
);


CREATE TABLE "AppSettings" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "Key" text NOT NULL,
    "Value" text NOT NULL,
    "CreatedAt" timestamp with time zone NOT NULL,
    "CreatedBy" integer,
    "UpdatedAt" timestamp with time zone,
    "UpdatedBy" integer,
    CONSTRAINT "PK_AppSettings" PRIMARY KEY ("Id")
);


CREATE TABLE "CalendarEvents" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "EventDate" timestamp with time zone NOT NULL,
    "Description" text NOT NULL,
    "CreatedAt" timestamp with time zone NOT NULL,
    "CreatedBy" integer,
    "UpdatedAt" timestamp with time zone,
    "UpdatedBy" integer,
    CONSTRAINT "PK_CalendarEvents" PRIMARY KEY ("Id")
);


CREATE TABLE "Clients" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "Name" text NOT NULL,
    "Profession" text,
    "MatriculeFiscale" text,
    "Email" text,
    "Telephone" text,
    "Portable" text,
    "Fax" text,
    "Adresse" text,
    "CodePostal" text,
    "Ville" text,
    "Pays" text,
    "Banque" text,
    "RIB" text,
    "Note" text,
    "CreatedAt" timestamp with time zone NOT NULL,
    "CreatedBy" integer,
    "UpdatedAt" timestamp with time zone,
    "UpdatedBy" integer,
    "IsDeleted" boolean NOT NULL,
    CONSTRAINT "PK_Clients" PRIMARY KEY ("Id")
);


CREATE TABLE "Depenses" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "DateDepense" timestamp with time zone NOT NULL,
    "Libelle" text NOT NULL,
    "Montant" numeric NOT NULL,
    "Description" text NOT NULL,
    "CreatedAt" timestamp with time zone NOT NULL,
    "CreatedBy" integer,
    "UpdatedAt" timestamp with time zone,
    "UpdatedBy" integer,
    CONSTRAINT "PK_Depenses" PRIMARY KEY ("Id")
);


CREATE TABLE "Produits" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "Marque" text,
    "Famille" text,
    "Designation" text NOT NULL,
    "PrixUnitaire" numeric(18,2),
    "CreatedAt" timestamp with time zone NOT NULL,
    "CreatedBy" integer,
    "UpdatedAt" timestamp with time zone,
    "UpdatedBy" integer,
    "IsDeleted" boolean NOT NULL,
    CONSTRAINT "PK_Produits" PRIMARY KEY ("Id")
);


CREATE TABLE "Roles" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "Name" text NOT NULL,
    "CreatedAt" timestamp with time zone NOT NULL,
    "CreatedBy" integer,
    "UpdatedAt" timestamp with time zone,
    "UpdatedBy" integer,
    "IsDeleted" boolean NOT NULL,
    CONSTRAINT "PK_Roles" PRIMARY KEY ("Id")
);


CREATE TABLE "SavingEntries" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "Date" date NOT NULL,
    "Amount" numeric(8,2) NOT NULL,
    "CreatedAt" timestamp with time zone NOT NULL,
    CONSTRAINT "PK_SavingEntries" PRIMARY KEY ("Id")
);


CREATE TABLE "Ventes" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "ClientId" integer NOT NULL,
    "DocumentNumber" text NOT NULL,
    "FactureNumber" text,
    "TotalAmount" numeric NOT NULL,
    "DateVente" timestamp with time zone NOT NULL,
    "DateLivraison" timestamp with time zone,
    "Etat" integer NOT NULL,
    "PaidAmount" numeric NOT NULL,
    "PaiementEtat" integer NOT NULL,
    "Note" text,
    "CreatedAt" timestamp with time zone NOT NULL,
    "CreatedBy" integer,
    "UpdatedAt" timestamp with time zone,
    "UpdatedBy" integer,
    CONSTRAINT "PK_Ventes" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_Ventes_Clients_ClientId" FOREIGN KEY ("ClientId") REFERENCES "Clients" ("Id") ON DELETE CASCADE
);


CREATE TABLE "AchatLignes" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "AchatId" integer NOT NULL,
    "ProduitId" integer NOT NULL,
    "Quantite" integer NOT NULL,
    "CreatedAt" timestamp with time zone NOT NULL,
    "CreatedBy" integer,
    "UpdatedAt" timestamp with time zone,
    "UpdatedBy" integer,
    CONSTRAINT "PK_AchatLignes" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_AchatLignes_Achats_AchatId" FOREIGN KEY ("AchatId") REFERENCES "Achats" ("Id") ON DELETE CASCADE,
    CONSTRAINT "FK_AchatLignes_Produits_ProduitId" FOREIGN KEY ("ProduitId") REFERENCES "Produits" ("Id") ON DELETE CASCADE
);


CREATE TABLE "StockMovements" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "ProduitId" integer NOT NULL,
    "Quantity" integer NOT NULL,
    "MovementType" text NOT NULL,
    "ReferenceId" integer,
    "CreatedAt" timestamp with time zone NOT NULL,
    "CreatedBy" integer,
    "UpdatedAt" timestamp with time zone,
    "UpdatedBy" integer,
    CONSTRAINT "PK_StockMovements" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_StockMovements_Produits_ProduitId" FOREIGN KEY ("ProduitId") REFERENCES "Produits" ("Id") ON DELETE CASCADE
);


CREATE TABLE "Users" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "Username" text NOT NULL,
    "Email" text,
    "PasswordHash" text NOT NULL,
    "RoleId" integer NOT NULL,
    "CreatedAt" timestamp with time zone NOT NULL,
    "CreatedBy" integer,
    "UpdatedAt" timestamp with time zone,
    "UpdatedBy" integer,
    "IsDeleted" boolean NOT NULL,
    CONSTRAINT "PK_Users" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_Users_Roles_RoleId" FOREIGN KEY ("RoleId") REFERENCES "Roles" ("Id") ON DELETE CASCADE
);


CREATE TABLE "Payments" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "ClientId" integer NOT NULL,
    "VenteId" integer,
    "Amount" numeric NOT NULL,
    "PaymentMode" text NOT NULL,
    "PaymentNumber" text,
    "PaymentDate" timestamp with time zone,
    "DueDate" timestamp with time zone,
    "IsReceived" boolean NOT NULL,
    "CalendarEventId" integer,
    "Note" text,
    "CreatedAt" timestamp with time zone NOT NULL,
    "CreatedBy" integer,
    "UpdatedAt" timestamp with time zone,
    "UpdatedBy" integer,
    "IsDeleted" boolean NOT NULL,
    CONSTRAINT "PK_Payments" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_Payments_Clients_ClientId" FOREIGN KEY ("ClientId") REFERENCES "Clients" ("Id") ON DELETE CASCADE,
    CONSTRAINT "FK_Payments_Ventes_VenteId" FOREIGN KEY ("VenteId") REFERENCES "Ventes" ("Id")
);


CREATE TABLE "VenteLignes" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "VenteId" integer NOT NULL,
    "ProduitId" integer NOT NULL,
    "Quantite" integer NOT NULL,
    "PrixUnitaire" numeric(18,2),
    "RemisePercent" numeric(5,2) NOT NULL,
    "CreatedAt" timestamp with time zone NOT NULL,
    "CreatedBy" integer,
    "UpdatedAt" timestamp with time zone,
    "UpdatedBy" integer,
    CONSTRAINT "PK_VenteLignes" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_VenteLignes_Produits_ProduitId" FOREIGN KEY ("ProduitId") REFERENCES "Produits" ("Id") ON DELETE CASCADE,
    CONSTRAINT "FK_VenteLignes_Ventes_VenteId" FOREIGN KEY ("VenteId") REFERENCES "Ventes" ("Id") ON DELETE CASCADE
);


CREATE INDEX "IX_AchatLignes_AchatId" ON "AchatLignes" ("AchatId");


CREATE INDEX "IX_AchatLignes_ProduitId" ON "AchatLignes" ("ProduitId");


CREATE UNIQUE INDEX "IX_AppSettings_Key" ON "AppSettings" ("Key");


CREATE INDEX "IX_CalendarEvents_EventDate" ON "CalendarEvents" ("EventDate");


CREATE INDEX "IX_Depenses_DateDepense" ON "Depenses" ("DateDepense");


CREATE UNIQUE INDEX "IX_Payments_CalendarEventId" ON "Payments" ("CalendarEventId");


CREATE INDEX "IX_Payments_ClientId" ON "Payments" ("ClientId");


CREATE INDEX "IX_Payments_VenteId" ON "Payments" ("VenteId");


CREATE UNIQUE INDEX "IX_SavingEntries_Date" ON "SavingEntries" ("Date");


CREATE INDEX "IX_StockMovements_ProduitId" ON "StockMovements" ("ProduitId");


CREATE INDEX "IX_Users_RoleId" ON "Users" ("RoleId");


CREATE UNIQUE INDEX "IX_Users_Username" ON "Users" ("Username");


CREATE INDEX "IX_VenteLignes_ProduitId" ON "VenteLignes" ("ProduitId");


CREATE INDEX "IX_VenteLignes_VenteId" ON "VenteLignes" ("VenteId");


CREATE INDEX "IX_Ventes_ClientId" ON "Ventes" ("ClientId");


CREATE UNIQUE INDEX "IX_Ventes_DocumentNumber" ON "Ventes" ("DocumentNumber");


